package com.ecommerce.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.Date;
@Service public class JwtService { private final SecretKey key; private final long expirationMs; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.expiration-ms}") long expirationMs){this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.expirationMs=expirationMs;} public String generateToken(UserDetails userDetails){Date now=new Date();return Jwts.builder().subject(userDetails.getUsername()).issuedAt(now).expiration(new Date(now.getTime()+expirationMs)).signWith(key).compact();} public String extractUsername(String token){return claims(token).getSubject();} public boolean isTokenValid(String token,UserDetails userDetails){return extractUsername(token).equals(userDetails.getUsername()) && claims(token).getExpiration().after(new Date());} private Claims claims(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();} }